 const covered=new Set(sections.flatMap(item=>item.sourcePositionIds)),remaining=answers.filter(item=>!covered.has(item.positionId));
 if(remaining.length)sections.push(runeSection("integration","Lo que completa la lectura",joinedCore(remaining),remaining,["integration"]));
