export function interpretRuneSpread(spreadDef:RuneSpread,drawn:RuneMeaning[]):RuneReading{
 if(drawn.length<spreadDef.positions.length)throw new Error(`${spreadDef.name} requiere ${spreadDef.positions.length} runas.`);
 const relations=spreadDef.positions.slice(0,-1).map((position,index)=>({id:`rune-relation:${spreadDef.id}:${index+1}`,from:position.id,to:spreadDef.positions[index+1].id,type:relationType(position,spreadDef.positions[index+1])}));
 const positionAnswers:RunePositionAnswer[]=spreadDef.positions.map((position,index)=>{const rune=drawn[index];return {positionId:position.id,position:position.label,role:position.role,runeId:rune.id,runeName:rune.name,answer:positionBody(rune,position),rune,sourceRuneIds:[rune.id],sourcePositionIds:[position.id],sourceRelationIds:relations.filter(relation=>relation.from===position.id||relation.to===position.id).map(relation=>relation.id)}});
 const verdict=spreadDef.id==="reasoned"?runeVerdict(positionAnswers):undefined,sections=runeEditorialSections(spreadDef,positionAnswers,verdict);
 for(const section of sections)section.sourceRelationIds=relations.filter(relation=>section.sourcePositionIds.includes(relation.from)&&section.sourcePositionIds.includes(relation.to)).map(relation=>relation.id);
 const story=sections.map(item=>item.body),main=story.join(" "),riskAnswer=positionAnswers.find(item=>item.role==="risk"||item.role==="obstacle"||item.role==="shadow")||positionAnswers.find(item=>item.rune.tone==="restrictive"),actionAnswer=positionAnswers.find(item=>item.role==="action"||item.role==="advice")||positionAnswers.find(item=>item.rune.tone==="supportive"),rawCaution=riskAnswer?.rune.risk||"No conviertas una señal simbólica en una certeza; comprueba su relación con los hechos.",rawAdvice=actionAnswer?`${actionAnswer.rune.resource} ${actionAnswer.rune.action}`:"Define una acción pequeña, observa su efecto y ajusta antes de comprometer más recursos.";
 const caution=semanticOverlap(rawCaution,main)>.46?"":sentence(rawCaution),advice=semanticOverlap(rawAdvice,main)>.46||semanticOverlap(rawAdvice,caution)>.38?"":sentence(rawAdvice),sourceRuneIds=unique(positionAnswers.map(item=>item.runeId)),sourcePositionIds=unique(positionAnswers.map(item=>item.positionId)),sourceRelationIds=unique(relations.map(item=>item.id));
 const summary=`${verdict?`${verdict}. `:""}${sections[0].body}${sections.length>1?` ${sections.at(-1)!.body}`:""}`;
 const title=verdict?"Respuesta razonada":spreadDef.id==="feel-think-act"?"Emoción, pensamiento y conducta":spreadDef.id==="two-paths"||spreadDef.id==="act-or-not"?"Comparación de alternativas":spreadDef.id==="opportunity-risk-strategy"?"La oportunidad y cómo aprovecharla":spreadDef.id==="shadow-learning-resource"?"Del patrón a la respuesta":spreadDef.id==="rune-cross-nine"?"La situación y su posible salida":spreadDef.positions.length>7?"La historia que forman las runas":"Lo que esta tirada muestra";
 return {title,sections,positionAnswers,story,summary,verdict,warning:caution||rawCaution,showWarning:Boolean(caution),warningTitle:"Lo que debes cuidar",caution,showAdvice:Boolean(advice),adviceTitle:"Qué puedes hacer ahora",advice,narrativeSynthesis:{readingThesis:sections[0]?.body||"",mainMovement:sections.at(-1)?.body||"",sourceRuneIds,sourcePositionIds,sourceRelationIds},debug:{spreadId:spreadDef.id,relations}};
}

