export function castIChing(random=()=>Math.random()):IChingLine[]{
 return Array.from({length:6},()=>{const value=(Array.from({length:3},()=>random()<.5?2:3).reduce((sum,item)=>sum+item,0)) as 6|7|8|9;return {value,yang:value===7||value===9,changing:value===6||value===9};});
}

